import base64
import json
import os
from typing import Any, Dict, List, Optional

import boto3


def _read_document_bytes(document: Any) -> bytes:
    if document is None:
        raise ValueError("document must not be None")
    if isinstance(document, bytes):
        return document
    if isinstance(document, str):
        if os.path.exists(document):
            with open(document, "rb") as f:
                return f.read()
        # Treat as base64-encoded content if it is not a file path
        try:
            return base64.b64decode(document, validate=True)
        except Exception as e:
            raise ValueError("document string must be a valid file path or base64-encoded content") from e
    if hasattr(document, "read"):
        data = document.read()
        if isinstance(data, str):
            return data.encode("utf-8")
        return data
    raise TypeError("document must be bytes, a file path string, base64 string, or a file-like object")


def _get_textract_client(region_name: Optional[str] = None):
    return boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))


def _block_bbox(block: Dict[str, Any]) -> Optional[Dict[str, float]]:
    geometry = block.get("Geometry") or {}
    bbox = geometry.get("BoundingBox")
    if not bbox:
        return None
    return {
        "left": float(bbox.get("Left", 0.0)),
        "top": float(bbox.get("Top", 0.0)),
        "width": float(bbox.get("Width", 0.0)),
        "height": float(bbox.get("Height", 0.0)),
    }


def _block_polygon(block: Dict[str, Any]) -> Optional[List[Dict[str, float]]]:
    geometry = block.get("Geometry") or {}
    polygon = geometry.get("Polygon")
    if not polygon:
        return None
    return [{"x": float(p.get("X", 0.0)), "y": float(p.get("Y", 0.0))} for p in polygon]


def _extract_text_from_relationships(block: Dict[str, Any], blocks_by_id: Dict[str, Dict[str, Any]]) -> str:
    parts: List[str] = []
    for rel in block.get("Relationships", []) or []:
        if rel.get("Type") in ("CHILD", "MERGED_CELL"):
            for child_id in rel.get("Ids", []) or []:
                child = blocks_by_id.get(child_id)
                if not child:
                    continue
                child_type = child.get("BlockType")
                if child_type == "WORD":
                    parts.append(child.get("Text", ""))
                elif child_type == "SELECTION_ELEMENT":
                    parts.append("[X]" if child.get("SelectionStatus") == "SELECTED" else "[ ]")
    return " ".join(p for p in parts if p).strip()


def _extract_table(block: Dict[str, Any], blocks_by_id: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
    rows: Dict[int, Dict[int, str]] = {}
    cells: List[Dict[str, Any]] = []

    for rel in block.get("Relationships", []) or []:
        if rel.get("Type") != "CHILD":
            continue
        for cell_id in rel.get("Ids", []) or []:
            cell = blocks_by_id.get(cell_id)
            if not cell or cell.get("BlockType") != "CELL":
                continue
            row_index = int(cell.get("RowIndex", 0))
            col_index = int(cell.get("ColumnIndex", 0))
            text = _extract_text_from_relationships(cell, blocks_by_id)
            rows.setdefault(row_index, {})[col_index] = text
            cells.append(
                {
                    "row_index": row_index,
                    "column_index": col_index,
                    "row_span": int(cell.get("RowSpan", 1)),
                    "column_span": int(cell.get("ColumnSpan", 1)),
                    "text": text,
                    "bbox": _block_bbox(cell),
                    "polygon": _block_polygon(cell),
                    "confidence": float(cell.get("Confidence", 0.0)),
                }
            )

    max_row = max(rows.keys(), default=0)
    max_col = max((max(cols.keys()) for cols in rows.values()), default=0)
    matrix: List[List[str]] = []
    for r in range(1, max_row + 1):
        row = []
        for c in range(1, max_col + 1):
            row.append(rows.get(r, {}).get(c, ""))
        matrix.append(row)

    return {
        "bbox": _block_bbox(block),
        "polygon": _block_polygon(block),
        "confidence": float(block.get("Confidence", 0.0)),
        "cells": cells,
        "matrix": matrix,
    }


def extract_layout_elements(document: Any, region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Extract blocks, lines, tables, and other layout elements from a document using Amazon Textract.

    Args:
        document: File path, bytes, base64-encoded string, or file-like object.
        region_name: Optional AWS region for the Textract client.

    Returns:
        Dict containing extracted layout elements:
            - pages
            - blocks
            - lines
            - tables
            - key_value_pairs
    """
    client = _get_textract_client(region_name=region_name)
    document_bytes = _read_document_bytes(document)

    response = client.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=["TABLES", "FORMS", "LAYOUT"],
    )

    blocks = response.get("Blocks", []) or []
    blocks_by_id = {b.get("Id"): b for b in blocks if b.get("Id")}

    pages: Dict[int, Dict[str, Any]] = {}
    lines: List[Dict[str, Any]] = []
    tables: List[Dict[str, Any]] = []
    key_value_pairs: List[Dict[str, Any]] = []

    for block in blocks:
        block_type = block.get("BlockType")
        page_num = int(block.get("Page", 1))

        if page_num not in pages:
            pages[page_num] = {"page": page_num, "blocks": [], "lines": [], "tables": []}

        normalized = {
            "id": block.get("Id"),
            "type": block_type,
            "text": block.get("Text", ""),
            "confidence": float(block.get("Confidence", 0.0)),
            "bbox": _block_bbox(block),
            "polygon": _block_polygon(block),
            "page": page_num,
        }

        if block_type in {"LINE", "WORD", "TABLE", "CELL", "KEY_VALUE_SET", "SELECTION_ELEMENT", "LAYOUT_TEXT", "LAYOUT_TITLE",
                          "LAYOUT_HEADER", "LAYOUT_FOOTER", "LAYOUT_SECTION_HEADER", "LAYOUT_PAGE_NUMBER", "LAYOUT_LIST",
                          "LAYOUT_FIGURE", "LAYOUT_TABLE", "LAYOUT_KEY_VALUE", "LAYOUT_GRAPHICAL_ELEMENT", "LAYOUT_SECTION_TITLE"}:
            pages[page_num]["blocks"].append(normalized)

        if block_type == "LINE":
            line = dict(normalized)
            line["text"] = block.get("Text", "")
            lines.append(line)
            pages[page_num]["lines"].append(line)

        elif block_type == "TABLE":
            table = {"page": page_num, **_extract_table(block, blocks_by_id)}
            tables.append(table)
            pages[page_num]["tables"].append(table)

        elif block_type == "KEY_VALUE_SET":
            entity_types = block.get("EntityTypes", []) or []
            if "KEY" in entity_types:
                key_text = _extract_text_from_relationships(block, blocks_by_id)
                value_text = ""
                for rel in block.get("Relationships", []) or []:
                    if rel.get("Type") == "VALUE":
                        for value_id in rel.get("Ids", []) or []:
                            value_block = blocks_by_id.get(value_id)
                            if value_block:
                                value_text = _extract_text_from_relationships(value_block, blocks_by_id)
                                break
                key_value_pairs.append(
                    {
                        "page": page_num,
                        "key": key_text,
                        "value": value_text,
                        "bbox": _block_bbox(block),
                        "polygon": _block_polygon(block),
                        "confidence": float(block.get("Confidence", 0.0)),
                    }
                )

    output = {
        "pages": [pages[p] for p in sorted(pages.keys())],
        "blocks": [
            {
                "id": b.get("Id"),
                "type": b.get("BlockType"),
                "text": b.get("Text", ""),
                "confidence": float(b.get("Confidence", 0.0)),
                "bbox": _block_bbox(b),
                "polygon": _block_polygon(b),
                "page": int(b.get("Page", 1)),
                "entity_types": b.get("EntityTypes", []) or [],
                "selection_status": b.get("SelectionStatus"),
            }
            for b in blocks
        ],
        "lines": lines,
        "tables": tables,
        "key_value_pairs": key_value_pairs,
        "raw_response": response,
    }
    return output


def extract_layout_elements_json(document: Any, region_name: Optional[str] = None) -> str:
    return json.dumps(extract_layout_elements(document, region_name=region_name), ensure_ascii=False, default=str)
